// A TypeScript port of backend/guardrails/detectors.py (the input side), so the demo masks and refuses the same things.
// guardrails.test.ts checks it against output generated by the Python original.

export interface Finding {
  kind: string;
  category: 'secret' | 'pii';
  start: number;
  end: number;
}

const luhn = (digits: string): boolean => {
  let total = 0;
  let flip = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits[i]);
    if (flip) d = d * 2 > 9 ? d * 2 - 9 : d * 2;
    total += d;
    flip = !flip;
  }
  return total % 10 === 0;
};

const validCard = (raw: string): boolean => {
  const digits = raw.replace(/\D/g, '');
  return digits.length >= 13 && digits.length <= 19 && new Set(digits).size > 1 && luhn(digits);
};

const validSsn = (raw: string): boolean => {
  const [area, group, serial] = raw.split('-');
  return area !== '000' && area !== '666' && !area.startsWith('9') && group !== '00' && serial !== '0000';
};

const validIban = (raw: string): boolean => {
  const iban = raw.replace(/\s/g, '').toUpperCase();
  if (iban.length < 15 || iban.length > 34) return false;
  const rearranged = iban.slice(4) + iban.slice(0, 4);
  const digits = [...rearranged].map((c) => parseInt(c, 36).toString()).join('');
  let rem = 0;
  for (const ch of digits) rem = (rem * 10 + Number(ch)) % 97; // BigInt-free mod 97
  return rem === 1;
};

const validPhone = (raw: string): boolean => {
  const digits = raw.replace(/\D/g, '');
  if (digits.length < 10 || digits.length > 15) return false;
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw.trim())) return false;
  return /[\s().-]/.test(raw) || raw.startsWith('+');
};

const validAssignmentValue = (value: string): boolean => /\d/.test(value) || !/^[A-Za-z]+$/.test(value);

type Validator = (raw: string) => boolean;
// [label, category, regex, validator, capture group to mask]. Earlier entries win an overlap.
const PATTERNS: [string, 'secret' | 'pii', RegExp, Validator | null, number][] = [
  ['PRIVATE_KEY', 'secret', /-----BEGIN [A-Z ]*PRIVATE KEY-----(?:.*?-----END [A-Z ]*PRIVATE KEY-----|.*$)/gs, null, 0],
  ['API_KEY', 'secret', /\b(?:sk-(?:proj-|ant-)?[A-Za-z0-9_-]{20,}|gsk_[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{16}|AIza[0-9A-Za-z_-]{35}|gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}|xox[abprs]-[A-Za-z0-9-]{10,}|hf_[A-Za-z0-9]{30,})/g, null, 0],
  ['JWT', 'secret', /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, null, 0],
  ['BEARER_TOKEN', 'secret', /\bBearer\s+([A-Za-z0-9._~+/=-]{20,})/g, null, 1],
  ['CREDENTIAL', 'secret', /\b(?:password|passwd|pwd|secret|api[_-]?key|access[_-]?token|auth[_-]?token|token)\b\s*[:=]\s*["']?([^\s"']{7,}[^\s"'.,;:!?)\]}])/gi, validAssignmentValue, 1],
  ['CARD', 'pii', /(?<![\w-])(?:\d[ -]?){12,18}\d(?![\w-])/g, validCard, 0],
  ['SSN', 'pii', /(?<![\w-])\d{3}-\d{2}-\d{4}(?![\w-])/g, validSsn, 0],
  ['IBAN', 'pii', /\b[A-Z]{2}\d{2}(?: ?[A-Z0-9]{4}){2,7}(?: ?[A-Z0-9]{1,3})?\b/g, validIban, 0],
  ['EMAIL', 'pii', /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, null, 0],
  ['PHONE', 'pii', /(?<![\w.-])\+?\d[\d\s().-]{8,18}\d(?![\w-])/g, validPhone, 0],
];

export function find(text: string, category?: 'secret' | 'pii'): Finding[] {
  const found: (Finding & { priority: number })[] = [];
  PATTERNS.forEach(([kind, cat, pattern, validator, group], priority) => {
    if (category && cat !== category) return;
    for (const m of text.matchAll(pattern)) {
      const value = m[group];
      if (value === undefined || (validator && !validator(value))) continue;
      // The mask covers the capture group, which sits inside the whole match.
      const start = group ? m.index + m[0].indexOf(value) : m.index;
      found.push({ kind, category: cat, start, end: start + value.length, priority });
    }
  });
  found.sort((a, b) => a.priority - b.priority || b.end - b.start - (a.end - a.start));
  const kept: Finding[] = [];
  for (const f of found) if (kept.every((k) => f.end <= k.start || f.start >= k.end)) kept.push(f);
  return kept.sort((a, b) => a.start - b.start);
}

export function redact(text: string, findings: Finding[]): string {
  let out = '';
  let pos = 0;
  for (const f of findings) {
    out += text.slice(pos, f.start) + `[REDACTED:${f.kind}]`;
    pos = f.end;
  }
  return out + text.slice(pos);
}

export function summarize(findings: Finding[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const f of findings) counts[f.kind] = (counts[f.kind] ?? 0) + 1;
  return counts;
}

const INJECTION =
  /\b(?:ignore|disregard|forget)\b[^.\n]{0,40}\b(?:previous|prior|above|earlier|all|any)\b[^.\n]{0,30}\b(?:instructions?|prompts?|rules)\b|\b(?:reveal|show|print|repeat)\b[^.\n]{0,30}\b(?:system prompt|hidden instructions)\b|\byou are now\b[^.\n]{0,40}\b(?:unrestricted|jailbroken|dan)\b/i;
export const looksLikeInjection = (text: string): boolean => INJECTION.test(text);

export const BLOCKED_SECRET =
  'That looks like it contains a secret (an API key, token, password or private key), so it was not sent or saved. Remove it and try again.';

export interface Checked {
  text: string;
  redacted: Record<string, number>;
}

/** Demo policy is fixed to the backend defaults: refuse secrets, mask personal data. */
export function checkInput(text: string): Checked | { blocked: string } {
  if (find(text, 'secret').length > 0) return { blocked: BLOCKED_SECRET };
  const findings = find(text);
  if (findings.length === 0) return { text, redacted: {} };
  return { text: redact(text, findings), redacted: summarize(findings) };
}
